    """Dehydrator for `timedelta` values.

    :param value: a datetime.timedelta instance
    :type value: datetime.timedelta
    :return: total seconds as float
    """
    if value is None:
        return None
    try:
        total = value.total_seconds()
    except AttributeError:
        raise TypeError(f"Expected a datetime.timedelta instance, got {type(value).__name__}")
    except Exception as exc:
        raise RuntimeError(f"Error converting timedelta to total seconds: {exc}") from exc
    if not isinstance(total, (int, float)):
        raise TypeError(f"Unexpected result type from total_seconds: {type(total).__name__}")
    return total

def dehydrate_time(value):
    """Dehydrator for `time` values.

    Converts a time-like object to its ISO 8601 string representation.
    If the input is None, None is returned. If the input does not
    provide an ``isoformat`` method, a ``TypeError`` is raised.

    :param value: The time-like object to dehydrate.
    :type value: datetime.time or similar
    :return: ISO 8601 string representation of the time, or None.
