        raise TypeError("fields must be a list or tuple of field names")
    for f in fields:
        if not isinstance(f, str) or not f:
            raise TypeError("each field name must be a non-empty string")
    # Validate srid_map
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dictionary")
    for k in srid_map:
        if not isinstance(k, int):
            raise TypeError("srid_map keys must be integers")
    # Prepare class dictionary
    class_dict = {
        'fields': tuple(fields),
        'srid_map': srid_map,
        '__module__': __name__,
    }
    # Define __init__ to accept field values
    def __init__(self, *args, **kwargs):
        # Call base class constructor if it exists
        try:
            super(self.__class__, self).__init__()
        except Exception:
            pass
        # Set attributes from kwargs
        for key, value in kwargs.items():
            if key in fields:
                setattr(self, key, value)
            else:
                raise AttributeError(f"Unknown field '{key}' for {name}")
    class_dict['__init__'] = __init__
    # Define __repr__ for debugging
    def __repr__(self):
        field_str = ', '.join(f"{k}={getattr(self, k, None)!r}" for k in fields)
        return f"<{name} {field_str}>"
    class_dict['__repr__'] = __repr__
    # Create the new class
    try:
        new_cls = type(name, (Point,), class_dict)
    except NameError as e:
        raise NameError("Base class 'Point' is not defined") from e
    except Exception as e:
        raise RuntimeError(f"Failed to create class '{name}': {e}") from e
    return new_cls

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError(f"Expected a string, got {type(s).__name__}")
    try:
        parts = []
        current = ""
        for ch in s:
            if ch.isdigit():
                current += ch
            else:
                if current:
                    parts.append(int(current))
                    current = ""
        if current:
            parts.append(int(current))
        return tuple(parts)
