def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if not isinstance(maxsize, int) or maxsize <= 0:
        raise ValueError("maxsize must be a positive integer")
    if not isinstance(ttl, (int, float)) or ttl < 0:
        raise ValueError("ttl must be a non‑negative number")
    if not callable(timer):
        raise TypeError("timer must be a callable returning a monotonic time")
    if not isinstance(typed, bool):
        raise TypeError("typed must be a boolean")

    from collections import OrderedDict
    from functools import wraps

    def decorator(func):
        cache = OrderedDict()

        @wraps(func)
        def wrapper(*args, **kwargs):
            # Build a hashable key that optionally includes argument types
            key_items = []
            for arg in args:
                key_items.append((arg, type(arg)) if typed else arg)
            for k, v in sorted(kwargs.items()):
                key_items.append((k, v, type(v)) if typed else (k, v))
            try:
                key = tuple(key_items)
            except TypeError:
                # Unhashable arguments; bypass caching
                return func(*args, **kwargs)

            now = timer()
            entry = cache.get(key)
            if entry is not None:
                value, ts = entry
                if now - ts <= ttl:
                    # Move to the end to mark as recently used
                    cache.move_to_end(key)
                    return value
                # Entry expired; remove it
                del cache[key]

            # Compute the result and cache it
            result = func(*args, **kwargs)
            cache[key] = (result, now)
            # Ensure cache size does not exceed maxsize
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return result

        return wrapper

    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if maxsize is not None and maxsize < 0:
        raise ValueError("maxsize must be >= 0 or None")
    def decorating_function(user_function):
        cache = {}
        order = []  # most recent first
        hits = misses = 0

        def _make_key(args, kwargs):
            key = args
            if kwargs:
                # sort kwargs to make key order-independent
                key += tuple(sorted(kwargs.items()))
            if typed:
                key += tuple(type(arg) for arg in args)
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))
            try:
                hash(key)
            except TypeError:
                raise TypeError("Arguments must be hashable")
            return key

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            key = _make_key(args, kwargs)
            if key in cache:
                # Move key to front (most recent)
                order.remove(key)
                order.insert(0, key)
                hits += 1

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    try:
        if key in self:
            return self[key]
        self[key] = default
        return default
    except TypeError as e:
        raise ValueError(f"Invalid or unhashable key: {key}") from e
    except Exception as e:
        raise RuntimeError(f"Error setting default for key {key}") from e

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    try:
        return self[key]
    except KeyError:
        return default
    except TypeError:
        # key is not hashable or self is not subscriptable
        return default
    except Exception:
        # Unexpected error: propagate to caller
        raise

@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    """
    try:
        if e is None:
            return "None"
        if not isinstance(e, BaseException):
            return str(e)
        tb = e.__traceback__
        if tb is None:
            return f"{type(e).__name__}: {e}"
        import traceback, os
        extracted = traceback.extract_tb(tb)
        lines = []
        for i, frame in enumerate(extracted[:max_level]):
            filename = frame.filename
            # Truncate path to the last max_path_level components
            parts = filename.split(os.sep)
            if len(parts) > max_path_level:
                filename = os.sep.join(parts[-max_path_level:])
            lines.append(f'  File "{filename}", line {frame.lineno}, in {frame.name}')
            if frame.line:
                lines.append(f'    {frame.line.strip()}')
        lines.append(f'{type(e).__name__}: {e}')
        return "\n".join(lines)
    except Exception as exc:
        return f"Error formatting exception: {exc}"

@staticmethod
def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    if not isinstance(file_name, str) or not file_name:
        return False
    try:
        import os
        return os.path.isfile(file_name)
    except Exception:
        return False

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    try:
        # Use the class name of the current instance
        name = self.__class__.__name__
        # Strip known suffixes
        for suffix in ("Py", "Fallback"):
