def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic validation
    try:
        bins_list = list(bins)
        edges_list = list(edges)
    except TypeError:
        raise TypeError("bins and edges must be iterable")

    if len(edges_list) != len(bins_list) + 1:
        raise ValueError("edges length must be one more than bins length")

    # Ensure edges are sorted and numeric
    for i in range(len(edges_list) - 1):
        try:
            left = float(edges_list[i])
            right = float(edges_list[i + 1])
        except (TypeError, ValueError):
            raise TypeError("edges must contain numeric values")
        if right <= left:
            raise ValueError("edges must be strictly increasing")

    # Compute integral
    total = 0.0
    for bin_val, left, right in zip(bins_list, edges_list, edges_list[1:]):
        try:
            bin_float = float(bin_val)
        except (TypeError, ValueError):
            raise TypeError("bins must contain numeric values")
        width = right - left
        total += bin_float * width

    return total

