            try:
                prefix = str(prefix)
            except Exception:
                raise TypeError("prefix must be a string or convertible to string")

        # Retrieve the log; fall back to empty if not present
        log = getattr(self, '_log', None)
        if log is None:
            return ''

        # If the log is a single string, just return it with prefix
        if isinstance(log, str):
            return f"{prefix}{log}"

        # If the log is an iterable of entries, format each line
        if isinstance(log, (list, tuple)):
            lines = []
            for entry in log:
                try:
                    entry_str = str(entry)
                except Exception:
                    entry_str = '<unprintable entry>'
