    # Perform simple validation based on the spec_version
    try:
        if spec_version == "1.0":
            required_keys = {"name", "items"}
            for key in required_keys:
                if key not in inventory:
                    raise ValueError(f"Missing required key '{key}' for spec_version 1.0")
            if not isinstance(inventory["name"], str):
                raise TypeError("inventory['name'] must be a string")
            if not isinstance(inventory["items"], list):
                raise TypeError("inventory['items'] must be a list")
        elif spec_version == "2.0":
            required_keys = {"id", "components"}
            for key in required_keys:
                if key not in inventory:
                    raise ValueError(f"Missing required key '{key}' for spec_version 2.0")
            if not isinstance(inventory["id"], (int, str)):
                raise TypeError("inventory['id'] must be an int or string")
            if not isinstance(inventory["components"], list):
                raise TypeError("inventory['components'] must be a list")
        else:
            # For unknown spec versions, perform minimal checks
            if "name" not in inventory:
                raise ValueError("Missing required key 'name' for unknown spec_version")
    except Exception as exc:
        # Wrap any exception to provide context
        raise ValueError(f"Inventory validation failed: {exc}") from exc

    # If all checks pass, return True
    return True

