def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import os
    import zipfile

    if not isinstance(zip_path, str):
        raise TypeError("zip_path must be a string path to a zip file")

    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            names = zf.namelist()
            # Find all XML files
            xml_files = [n for n in names if n.lower().endswith('.xml')]
            for xml_file in xml_files:
                # Base name without extension
                basename = os.path.splitext(os.path.basename(xml_file))[0]
                # Read XML content
                try:
                    xml_bytes = zf.read(xml_file)
                    xml_content = xml_bytes.decode('utf-8')
                except Exception:
                    xml_content = None
                # Find other files with the same base name
                related_files = {}
                for n in names:
                    if n == xml_file:
                        continue
                    if os.path.splitext(os.path.basename(n))[0] == basename:
                        try:
                            related_files[n] = zf.read(n)
                        except Exception:
                            # Skip files that cannot be read
                            pass
                result[basename] = {'xml': xml_content, 'files': related_files}
    except (FileNotFoundError, zipfile.BadZipFile, PermissionError) as exc:
        # If the zip file cannot be opened or read, return an empty dict
        # Optionally, you could log the exception here
        return {}
    except Exception:
        # Catch-all for any other unexpected errors
        return {}

    return result

