def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    if hook is None:
        raise ValueError("hook must not be None")
    def decorator(func):
        if not callable(func):
            raise TypeError("listener must be callable")
        try:
            listeners = getattr(self, "_registry", None)
            if listeners is None:
                listeners = {}
                setattr(self, "_registry", listeners)
            listeners.setdefault(hook, []).append(func)
        except Exception as e:
            raise RuntimeError(f"Failed to register listener for hook {hook}") from e
        return func
    return decorator

