            existing_key_node, existing_value_node = result[idx]
            # Merge logic
            if hasattr(existing_value_node, 'tag') and hasattr(value_node, 'tag'):
                # Both are mapping nodes?
                if existing_value_node.tag == 'tag:yaml.org,2002:map' and value_node.tag == 'tag:yaml.org,2002:map':
                    # Merge mapping values recursively
                    merged = deep_merge_nodes(existing_value_node.value + value_node.value)
                    new_value_node = type(existing_value_node)(tag=existing_value_node.tag, value=merged)
                    result[idx] = (existing_key_node, new_value_node)
                else:
                    # Non-mapping or different tags: last wins
                    result[idx] = (existing_key_node, value_node)
            else:
                # One or both are not mapping nodes: last wins
                result[idx] = (existing_key_node, value_node)
        else:
            key_index[key] = len(result)
            result.append((key_node, value_node))
    return result

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Validate input
    if parser is None:
        raise TypeError("parser must not be None")
    if not hasattr(parser, "_actions"):
        raise TypeError("Expected an argparse.ArgumentParser instance")
    flags = []
    for action in parser._actions:
        try:
            opt_strings = getattr(action, "option_strings", [])
            if opt_strings:
                flags.extend(opt_strings)
        except Exception:
            # Skip actions that do not expose option_strings
            continue
    return " ".join(flags)

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate input types
    if not isinstance(response, list):
        raise TypeError("response must be a list")
    if not isinstance(max_results, int) or max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    # Generate pages
    try:
        for start in range(0, len(response), max_results):
            yield response[start:start + max_results]
    except Exception as exc:
        # In case of unexpected errors during iteration
        raise RuntimeError(f"Error while paging through response: {exc}") from exc

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError("Input must be an iterable of dictionaries, got None")
    result = {}
    for idx, d in enumerate(dicts):
        if not isinstance(d, dict):
            raise TypeError(f"Item at index {idx} is not a dict: {d!r}")
        for key, value in d.items():
            if not isinstance(value, (int, float)):
                raise TypeError(f"Value for key {key!r} is not numeric: {value!r}")
            result[key] = result.get(key, 0) + value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    # Validate input types
    if not isinstance(url, str):
        raise TypeError(f"url must be a string, got {type(url).__name__}")
    if url_args is None:
        url_args = {}
    if not isinstance(url_args, dict):
        raise TypeError(f"url_args must be a dict, got {type(url_args).__name__}")

    # If there are no arguments to replace, return the original URL
    if not url_args:
        return url

    import re
    from urllib.parse import quote

    # Pattern to find placeholders like {key}
    placeholder_pattern = re.compile(r'\{([^{}]+)\}')

    def _replace_match(match):
        key = match.group(1)
        if key not in url_args:
            raise KeyError(f"Missing URL argument: {key}")
        value = url_args[key]
        # Convert the value to string and URL‑encode it
        return quote(str(value), safe='')

    # Perform the substitution
    try:
        return placeholder_pattern.sub(_replace_match, url)
    except re.error as exc:
        # In case the regex fails (unlikely with a static pattern)
        raise RuntimeError(f"Regex error while replacing URL arguments: {exc}") from exc
    except Exception as exc:
        # Catch any other unexpected errors
        raise RuntimeError(f"Error while replacing URL arguments: {exc}") from exc

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    try:
        if not isinstance(val, str):
            return False
        return val.strip().lower() in ("none", "null", "nil")
    except Exception:
        return False

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Validate that the parser has the expected attribute
    if not hasattr(parser, "_actions"):
        raise TypeError("Expected an argparse.ArgumentParser instance")
    try:
        flags = []
        for action in parser._actions:
            # Some actions (e.g., positional arguments) have no option_strings
            if hasattr(action, "option_strings"):
                flags.extend(action.option_strings)
        # Preserve order while removing duplicates
        seen = set()
        unique_flags = [f for f in flags if not (f in seen or seen.add(f))]
        return " ".join(unique_flags)
    except Exception as exc:
        # Re-raise as a generic exception with context
        raise RuntimeError(f"Failed to extract flags from parser: {exc}") from exc

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    # Validate inputs
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    if not isinstance(register_number, int):
        raise TypeError("register_number must be an integer")
    if not isinstance(register_value, str):
        raise TypeError("register_value must be a string key")

    # Iterate over each flow and replace the specified key's value
    for flow_key, flow in flow_params.items():
        if isinstance(flow, dict) and register_value in flow:
            flow[register_value] = register_number

    return flow_params

