def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not isinstance(host, str):
        return False
    host = host.strip()
    if not host:
        return False
    # Direct string check for common localhost names
    if host.lower() == "localhost":
        return True
    try:
        # Resolve the host to all possible addresses
        addr_info = socket.getaddrinfo(host, None)
    except (socket.gaierror, socket.herror, socket.timeout):
        return False
    for info in addr_info:
        # info[4] is a tuple like (address, port, flowinfo, scopeid) for IPv6
        address = info[4][0]
        if address in ("127.0.0.1", "::1"):
            return True
    return False

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # In Git Bash on Windows, os.name is 'posix' but MSYSTEM env var is set
        if os.name != 'posix':
            return False
        # Check for typical Git Bash environment variables
        if 'MSYSTEM' in os.environ:
            return True
        # Some setups may use OSTYPE
        if os.environ.get('OSTYPE', '').startswith('msys'):
            return True
        return False
    except Exception:
        # In case of any unexpected error, default to False
        return False

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Validate matcher type
    if not isinstance(matcher, (tuple, list)):
        raise TypeError("matcher must be a tuple or list containing the variable name and optional default value")

    # Extract name and default
    if len(matcher) == 1:
        name = matcher[0]
        default = None
    elif len(matcher) == 2:
        name, default = matcher
    else:
        raise ValueError("matcher must contain 1 or 2 elements: (name,) or (name, default)")

    if not isinstance(name, str):
        raise TypeError("environment variable name must be a string")

    # Retrieve from environment
    value = os.getenv(name)

    # Handle missing variable
    if value is None:
        if default is not None:
            return default
        else:
            raise KeyError(f"Environment variable '{name}' not found and no default provided")

    return value

