    import os
    import json

    # Helper to merge two dictionaries recursively
    def _merge_dicts(target, source):
        for key, value in source.items():
            if key in target and isinstance(target[key], dict) and isinstance(value, dict):
                target[key] = _merge_dicts(target[key], value)
            else:
                target[key] = value
        return target

    # Recursive resolver
    def _resolve(d, current_dir, visited):
        if not isinstance(d, dict):
            return d

        # Handle include directive at this level
        if 'include' in d:
            inc = d.pop('include')
            if isinstance(inc, str):
                inc_list = [inc]
            elif isinstance(inc, list):
                inc_list = inc
            else:
                raise ValueError(f"Invalid include value: {inc!r}")

            for inc_path in inc_list:
                if not isinstance(inc_path, str):
                    raise ValueError(f"Include path must be a string, got {inc_path!r}")
                abs_path = os.path.abspath(os.path.join(current_dir, inc_path))
                if abs_path in visited:
                    # Skip already processed files to avoid circular includes
                    continue
                visited.add(abs_path)
                try:
                    with open(abs_path, 'r', encoding='utf-8') as f:
                        inc_data = json.load(f)
                except FileNotFoundError:
                    raise FileNotFoundError(f"Included file not found: {abs_path}")
                except json.JSONDecodeError as e:
                    raise ValueError(f"Error decoding JSON in included file {abs_path}: {e}")

                # Resolve includes within the included data
                inc_resolved = _resolve(inc_data, os.path.dirname(abs_path), visited)
                # Merge into current dict
                d = _merge_dicts(d, inc_resolved)

        # Resolve nested structures
        for key, value in list(d.items()):
            if isinstance(value, dict):
                d[key] = _resolve(value, current_dir, visited)
            elif isinstance(value, list):
                new_list = []
                for item in value:
                    if isinstance(item, dict):
                        new_list.append(_resolve(item, current_dir, visited))
                    else:
                        new_list.append(item)
                d[key] = new_list

        return d

    # Validate input
    if not isinstance(parser_dict, dict):
        raise TypeError(f"parser_dict must be a dict, got {type(parser_dict).__name__}")

    # Determine base directory: use self.base_path if available, otherwise current working directory
    base_dir = getattr

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    try:
        spec = getattr(self, "spec", None)
        if not isinstance(spec, dict):
            raise TypeError("spec must be a dictionary")
        args = getattr(self, "args", {})
        if not isinstance(args, dict):
            args = {}
        for key, value in spec.items():
            # Skip if argument already provided
            if key in args:
                continue
            # Expect each spec entry to be a dict that may contain a 'default' key
            if isinstance(value, dict) and "default" in value:
                defaults[key] = value["default"]
    except Exception:
        # In case of any unexpected error, return an empty defaults dictionary
        return {}
    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
