        return {
            'old_option': 'new_option',
            'legacy_mode': 'mode',
            'use_legacy': 'use_new',
        }
    except Exception:
        # In case of unexpected errors, return an empty mapping.
        return {}

def validate_arg_deprecation(self, cli_args, answer_file_args):
        """Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args:  the dict of arguments from files
        """
        # Ensure inputs are dictionaries; treat None as empty dict
        if cli_args is None:
            cli_args = {}
        if answer_file_args is None:
            answer_file_args = {}
        if not isinstance(cli_args, dict):
            raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
        if not isinstance(answer_file_args, dict):
            raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

        # Mapping of deprecated argument names to their recommended replacements
        # This mapping can be extended as needed.
        deprecated_map = {
            "old_option": "new_option",
            "legacy_flag": "modern_flag",
            "deprecated_param": "updated_param",
            # Add more deprecated arguments here
        }

        # Check for deprecated arguments in the answer file
        for key in answer_file_args:
            if key in deprecated_map:
                new_key = deprecated_map[key]
                print(f"Warning: Argument '{key}' is deprecated in the answer file. "
                      f"Use '{new_key}' instead.")

        # Check for deprecated arguments in the CLI
        for key in cli_args:
            if key in deprecated_map:
                new_key = deprecated_map[key]
                print(f"Warning: Argument '{key}' is deprecated in the CLI. "
                      f"Use '{new_key}' instead.")

        # If a deprecated argument appears in both CLI and answer file, warn that CLI takes precedence
        for key in deprecated_map:
            if key in cli_args and key in answer_file_args:
                print(f"Warning: Deprecated argument '{key}' specified in both CLI and answer file. "
                      f"CLI value will be used.")

        # No return value; the method is used for side-effect (printing warnings) only.

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")

    try:
        # Retrieve the options dictionary; if it doesn't exist, treat as empty
        options_dict = getattr(self, "_command_options", {})
        if not isinstance(options_dict, dict):
            raise TypeError("Internal _command_options must be a dict")

        # Get the options for the requested command, defaulting to an empty list
        options = options_dict.get(command_name, [])
        if not isinstance(options, list):
            # If the stored value is not a list, attempt to convert it
            options = list(options)

        return options
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve parser options for '{command_name}': {exc}") from exc

def get_silent_args(self, args):
    """
    list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    silent = []
    if args is None:
        return silent
    try:
        # Handle dictionary of arguments
        if isinstance(args, dict):
            for key, value in args.items():
                if value is None or value is False:
                    silent.append(key)
            return silent

        # Handle list or tuple of arguments
        if isinstance(args, (list, tuple)):
            for item in args:
                # Tuple of (name, value)
                if isinstance(item, tuple) and len(item) == 2:
                    name, value = item
                    if value is None or value is False:
                        silent.append(name)
                    continue

                # String argument that might be considered silent
                if isinstance(item, str):
                    if item.startswith('_') or item.startswith('no_'):
                        silent.append(item)
                    continue

                # Object with 'silent' or 'is_silent' flag
                if hasattr(item, 'silent') and getattr(item, 'silent'):
                    name = getattr(item, 'name', None)
                    if name:
                        silent.append(name)
                    continue
                if hasattr(item, 'is_silent') and getattr(item, 'is_silent'):
                    name = getattr(item, 'name', None)
                    if name:
                        silent.append(name)
                    continue

                # Object with 'value' attribute that might be None or False
                if hasattr(item, 'value'):
                    if getattr(item, 'value') is None or getattr(item, 'value') is False:
                        name = getattr(item, 'name', None)
                        if name:
                            silent.append(name)
                    continue

                # Fallback: if item is a dict-like with a single key-value pair
                if isinstance(item, dict):
                    for key, value in item.items():
                        if value is None or value is False:
                            silent.append(key)
                    continue

            return silent
    except Exception:
        # In case of any unexpected error, return what we have collected so far
        return silent

    return silent

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Ensure args is a dictionary
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")

    # Retrieve the list of required arguments from the instance
    required = getattr(self, "required_args", None)
    if required is None:
        raise AttributeError("The instance does not define 'required_args'")

    if not isinstance(required, (list, tuple, set)):
        raise TypeError("'required_args' must be a list, tuple, or set")

    # Identify any missing arguments
    missing = [arg for arg in required if arg not in args or args[arg] is None]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")

    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        required = []
        if not options_spec:
            return required
        # Ensure args is a dict for evaluation
        if args is None:
            args = {}
        for opt in options_spec:
            name = opt.get("name")
            if not name:
                continue
            cond = opt.get("required_when")
            if cond is None:
                continue
            try:
                # If condition is a callable, call it with args
                if callable(cond):
                    if cond(args):
                        required.append(name)
                else:
                    # Evaluate string condition in the context of args
                    # Use empty globals for safety
                    if eval(cond, {}, args):
                        required.append(name)
            except Exception:
                # Ignore any errors in condition evaluation
                continue
        return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if args is None:
        raise TypeError("args cannot be None.")
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values.")
    # Determine max length mapping
    max_lengths = getattr(self, "max_lengths", {})
    for name, value in args.items():
        # Get max length for this argument
        max_len = max_lengths.get(name)
        if max_len is None:
            # Try attribute naming convention
            attr_name = f"max_length_{name}"
            max_len = getattr(self, attr_name, None)
        if max_len is None:
            # No max length specified, skip
            continue
        if not isinstance(max_len, int) or max_len < 0:
            raise ValueError(f"Invalid maximum length for argument '{name}'.")
        try:
            length = len(value)
        except TypeError:
            # Value has no length, skip
            continue
        if length > max_len:
            raise ValueError(f"Argument '{name}' length {length} exceeds maximum allowed {max_len}.")
    return True

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # Basic type checking for the input
        if args is None:
            raise TypeError("args must not be None")
        if not isinstance(args, dict):
            raise TypeError("args must be a dictionary of argument names to values")

        # If the class does not define any choices, nothing to validate
        choices_map = getattr(self, "choices", None)
        if not isinstance(choices_map, dict):
            return

        for arg_name, arg_value in args.items():
            # Skip arguments that have no defined choices
            if arg_name not in choices_map:
                continue

            allowed = choices_map[arg_name]
            # Ensure the allowed set is iterable
            try:
                iter(allowed)
            except TypeError:
                # If allowed is not iterable, skip validation for this argument
                continue

            # Skip validation if the argument value is None
            if arg_value is None:
                continue

            # If the argument value is a collection, validate each element
            if isinstance(arg_value, (list, tuple, set)):
                for val in arg_value:
                    if val not in allowed:
                        raise ValueError(
                            f"Invalid value '{val}' for argument '{arg_name}'. "
                            f"Allowed choices: {allowed}"
                        )
            else:
                if arg_value not in allowed:
                    raise ValueError(
                        f"Invalid value '{arg_value}' for argument '{arg_name}'. "
                        f"Allowed choices: {allowed}"
                    )

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    try:
        # Basic validation of required string parameters
        if not all(isinstance(x, str) and x for x in (subcommand, type_name, option_name)):
            raise ValueError("subcommand, type_name, and option_name must be non-empty strings")

        # spec_option must be a dictionary
        if not isinstance(spec_option, dict):
            raise TypeError("spec_option must be a dict")

        # Retrieve a parser callable from spec_option, default to identity
        parser = spec_option.get("parser")
        if parser is None:
            def parser(value):
                return value
        elif not callable(parser):
            raise TypeError("spec_option['parser'] must be callable")

        # Define the complex type function that will be used by the argument parser
        def complex_type(value):
            try:
                return parser(value)
            except Exception as e:
                raise ValueError(
                    f"Error parsing value for option '{option_name}' of type '{type_name}': {e}"
                ) from e

        # Give the function a helpful name for debugging
        complex_type.__name__ = f"{type_name}_{option_name}_parser"
        return complex_type

    except Exception as exc:
        # Wrap any exception in a RuntimeError to signal failure in type creation
        raise RuntimeError(
            f"Failed to create complex argument type for subcommand '{subcommand}': {exc}"
        ) from exc

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend ``vars_dict`` with ``extra-vars``.

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: Updated dictionary
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")

    if not extra_vars:
        return vars_dict

    # Accept a single string as a list of one element
    if isinstance(extra_vars, str):
        extra_vars = [extra_vars]

    if not isinstance(extra_vars, (list, tuple)):
        raise TypeError("extra_vars must be a list or tuple of strings")

    for var in extra_vars:
        if not isinstance(var, str):
            continue  # skip non-string entries

        if '=' not in var:
            continue  # skip malformed entries

        key, value = var.split('=', 1)
        key = key.strip()
        value = value.strip()

        if not key:
            continue  # skip if key is empty

        # Basic type conversion: bool, int, float
        lower_val = value.lower()
        if lower_val == 'true':
            value = True
        elif lower_val == 'false':
            value = False
        else:
            try:
                if '.' in value:
                    value = float(value)
                else:
                    value = int(value)
            except ValueError:
                # keep as string if conversion fails
                pass

        vars_dict[key] = value

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import os
    import json
    import subprocess

    # Validate inputs
    if not isinstance(playbook_path, str):
        raise TypeError("playbook_path must be a string")
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook '{playbook_path}' does not exist")

    if verbose is not None and not isinstance(verbose, int):
        raise TypeError("verbose must be an integer or None")

    if extra_vars is not None and not isinstance(extra_vars, dict):
        raise TypeError("extra_vars must be a dict or None")

    if ansible_args is not None and not isinstance(ansible_args, dict):
        raise TypeError("ansible_args must be a dict or None")

    # Build command
    cmd = ["ansible-playbook", playbook_path]

    if verbose:
        # Ansible uses -v, -vv, -vvv, etc.
        cmd.append("-" + "v" * verbose)

    if extra_vars:
        try:
            extra_json = json.dumps(extra_vars)
        except Exception as exc:
            raise ValueError("extra_vars must be JSON serializable") from exc
        cmd.extend(["--extra-vars", extra_json])

    if ansible_args:
        for key, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    cmd.append(f"--{key}")
                # skip false flags
                continue
            cmd.extend([f"--{key}", str(value)])

    # Logging
    if hasattr(ir_plugin, "logger"):
        ir_plugin.logger.debug(f"Running ansible-playbook command: {' '.join(cmd)}")
    else:
        print(f"Running ansible-playbook command: {' '.join(cmd)}")

    # Execute command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False,
        )
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook command not found") from exc
    except Exception as exc:
        raise RuntimeError(f"Error executing ansible-playbook: {exc}") from exc

    # Handle non-zero exit
    if result.returncode != 0:
        error_msg = (
            f"ansible-playbook exited with code {result.returncode}\n"
            f"stdout:\n{result.stdout}\n"
            f"stderr:\n{result.stderr}"
        )
        if hasattr(ir_plugin, "logger"):
            ir_plugin.logger.error(error_msg)
        raise RuntimeError(error_msg)

    # Return the CompletedProcess object for further inspection if needed
    return result

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    import glob

    # Validate input
    if not isinstance(plugin_dir, str):
        raise TypeError("plugin_dir must be a string path")
    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Directory not found: {plugin_dir}")

    # Locate the plugin spec file (plugin.yaml, plugin.yml, or plugin.json)
    spec_file = None
    for ext in ("yaml", "yml", "json"):
        matches = glob.glob(os.path.join(plugin_dir, f"plugin.{ext}"))
        if matches:
            spec_file = matches[0]
            break
    if not spec_file:
        raise FileNotFoundError("No plugin spec file found in directory")

    # Load the spec file
    try:
        with open(spec_file, "r", encoding="utf-8") as f:
            if spec_file.endswith(".json"):
                data = json.load(f)
            else:
                try:
                    import yaml
                except ImportError as exc:
                    raise ImportError(
                        "PyYAML is required to parse YAML plugin specs"
                    ) from exc
                data = yaml.safe_load(f)
    except Exception as exc:
        raise RuntimeError(f"Failed to load plugin spec: {exc}") from exc

    if not isinstance(data, dict):
        raise ValueError("Plugin spec must be a dictionary")

    # Helper to flatten nested structures
    def _flatten(d, parent_key=""):
        flat = {}
        for key, value in d.items():
            new_key = f"{parent_key}.{key}" if parent_key else str(key)
            if isinstance(value, dict):
                flat.update(_flatten(value, new_key))
            elif isinstance(value, list):
                for idx, item in enumerate(value):
                    list_key = f"{new_key}[{idx}]"
                    if isinstance(item, dict):
                        flat.update(_flatten(item, list_key))
                    else:
                        flat[list_key] = item
            else:
                flat[new_key] = value
        return flat

    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    env_var = "CONFIG_PATH"
    if env_var not in os.environ:
        try:
            default_path = os.path.join(os.getcwd(), "config.yaml")
            os.environ[env_var] = default_path
        except Exception as e:
            raise RuntimeError(f"Failed to set environment variable {env_var}: {e}") from e
